import assert from 'node:assert/strict'
import { mkdir, readFile, readdir, unlink, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'

const workspace = resolve(import.meta.dirname, '..')
const casesDirectory = resolve(workspace, 'benchmarks/conformance/cases')
const packageDirectory = resolve(workspace, 'packages/react-charts-catalog')
const outputDirectory = resolve(packageDirectory, 'src/cases')
const packagePath = resolve(packageDirectory, 'package.json')
const check = process.argv.includes('--check')
const generatedHeader =
  '// Generated by scripts/sync-react-charts-catalog.mjs.\n// Do not edit this file directly.\n'

const reactViewCaseIds = new Set([
  '80-echarts-axis-pointer',
  '81-recharts-interactive-legend',
  '82-chart-table-selection',
  '83-focus-context-window',
  '84-pinned-nested-chart-tooltip',
  '86-streaming-window-preservation',
  '87-echarts-synchronized-cursors',
  '88-echarts-free-cursor',
  '89-brush-range-selection',
  '90-zoomable-time-window',
])

const caseDirectories = (await readdir(casesDirectory, { withFileTypes: true }))
  .filter((entry) => entry.isDirectory())
  .map((entry) => entry.name)

const catalogCases = []
for (const directory of caseDirectories) {
  const metadataPath = resolve(casesDirectory, directory, 'case.json')
  let source
  try {
    source = await readFile(metadataPath, 'utf8')
  } catch (error) {
    if (error?.code === 'ENOENT') continue
    throw error
  }

  const metadata = JSON.parse(source)
  assert.equal(
    metadata.id,
    directory,
    `${metadataPath} id must match its directory`,
  )
  assert.equal(
    typeof metadata.order,
    'number',
    `${metadataPath} requires order`,
  )
  assert.equal(
    typeof metadata.title,
    'string',
    `${metadataPath} requires title`,
  )
  assert.equal(
    typeof metadata.family,
    'string',
    `${metadataPath} requires family`,
  )
  await readFile(resolve(casesDirectory, directory, 'tanstack.ts'), 'utf8')
  catalogCases.push({
    id: metadata.id,
    order: metadata.order,
    title: metadata.title,
    family: metadata.family,
  })
}

catalogCases.sort(
  (left, right) => left.order - right.order || left.id.localeCompare(right.id),
)
assert.equal(
  new Set(catalogCases.map(({ id }) => id)).size,
  catalogCases.length,
)
assert.equal(
  new Set(catalogCases.map(({ order }) => order)).size,
  catalogCases.length,
  'Catalog case order values must be unique',
)
for (const id of reactViewCaseIds) {
  assert.ok(
    catalogCases.some((catalogCase) => catalogCase.id === id),
    `Unknown React view catalog case ${id}`,
  )
}

let changed = false
changed =
  (await writeGenerated(
    resolve(packageDirectory, 'src/index.ts'),
    generateIndex(catalogCases),
  )) || changed

const expectedWrapperNames = new Set()
for (const catalogCase of catalogCases) {
  const name = `${catalogCase.id}.ts`
  expectedWrapperNames.add(name)
  changed =
    (await writeGenerated(
      resolve(outputDirectory, name),
      await generateWrapper(catalogCase.id),
    )) || changed
}

for (const entry of await readdir(outputDirectory, { withFileTypes: true })) {
  if (
    !entry.isFile() ||
    !entry.name.endsWith('.ts') ||
    expectedWrapperNames.has(entry.name)
  ) {
    continue
  }
  const path = resolve(outputDirectory, entry.name)
  const source = await readFile(path, 'utf8')
  if (!source.startsWith(generatedHeader)) continue
  changed = true
  if (!check) await unlink(path)
}

const packageManifest = JSON.parse(await readFile(packagePath, 'utf8'))
packageManifest.exports = sourceExports(catalogCases)
packageManifest.publishConfig.exports = publishedExports(catalogCases)
changed =
  (await writeGenerated(
    packagePath,
    `${JSON.stringify(packageManifest, null, 2)}\n`,
  )) || changed

if (check && changed) {
  throw new Error(
    'Generated React chart catalog is stale. Run pnpm react-catalog:sync and commit the result.',
  )
}

console.log(
  check
    ? `React chart catalog matches ${catalogCases.length} conformance cases.`
    : `Synchronized ${catalogCases.length} React chart catalog cases.`,
)

async function generateWrapper(id) {
  if (reactViewCaseIds.has(id)) {
    const viewPath = resolve(casesDirectory, id, 'view.tsx')
    const view = await readFile(viewPath, 'utf8')
    assert.match(
      view,
      /\bexport\s+(?:(?:const|let|var)\s+|function\s+)catalogComponent\b/u,
      `${viewPath} must export catalogComponent`,
    )
    return `${generatedHeader}import { catalogComponent } from '../../../../benchmarks/conformance/cases/${id}/view'\nimport { createCatalogView } from '../createCatalogView'\n\nexport default createCatalogView(catalogComponent)\n`
  }

  const implementationPath = resolve(casesDirectory, id, 'tanstack.ts')
  const implementation = await readFile(implementationPath, 'utf8')
  const hasCatalogCase =
    /\bexport\s+(?:(?:const|let|var)\s+|function\s+)catalogCase\b/u.test(
      implementation,
    )
  if (!hasCatalogCase) {
    assert.match(
      implementation,
      /\bexport\s+const\s+mount\s*=\s*tanstackMount\s*\(/su,
      `${implementationPath} must export catalogCase or an inferred tanstackMount descriptor`,
    )
  }
  const exportName = hasCatalogCase ? 'catalogCase' : 'mount as catalogCase'
  return `${generatedHeader}import { ${exportName} } from '../../../../benchmarks/conformance/cases/${id}/tanstack'\nimport { createCatalogChart } from '../createCatalogChart'\n\nexport default createCatalogChart(catalogCase)\n`
}

function generateIndex(cases) {
  const rows = cases
    .map(
      ({ id, order, title, family }) => `  {
    id: ${typescriptString(id)},
    order: ${order},
    title: ${typescriptString(title)},
    family: ${typescriptString(family)},
  },`,
    )
    .join('\n')
  return `${generatedHeader}export const catalogCases = [\n${rows}\n] as const\n\nexport type CatalogCaseId = (typeof catalogCases)[number]['id']\n\nexport interface CatalogChartProps {\n  initialWidth?: number\n  width?: number\n  height?: number\n  aspectRatio?: number\n  revision?: number\n  interactive?: boolean\n  preview?: boolean\n  idPrefix?: string\n}\n`
}

function sourceExports(cases) {
  return Object.fromEntries([
    ['.', './src/index.ts'],
    ...cases.map(({ id }) => [`./cases/${id}`, `./src/cases/${id}.ts`]),
  ])
}

function publishedExports(cases) {
  return Object.fromEntries([
    [
      '.',
      {
        types: './dist/index.d.ts',
        import: './dist/index.js',
      },
    ],
    ...cases.map(({ id }) => [
      `./cases/${id}`,
      {
        types: `./dist/cases/${id}.d.ts`,
        import: `./dist/cases/${id}.js`,
      },
    ]),
  ])
}

function typescriptString(value) {
  return `'${JSON.stringify(value).slice(1, -1).replaceAll("'", "\\'")}'`
}

async function writeGenerated(path, contents) {
  let current = null
  try {
    current = await readFile(path, 'utf8')
  } catch (error) {
    if (error?.code !== 'ENOENT') throw error
  }
  if (current === contents) return false
  if (!check) {
    await mkdir(dirname(path), { recursive: true })
    await writeFile(path, contents)
  }
  return true
}
